import { Result, wholeNumber } from "./validate";
import { MAX_PRICE } from "./listing";

type OfferTarget = { seller_id: string; allow_offers: boolean; sold_at: string | null };

export function offerBlockReason(post: OfferTarget, buyerId: string): string | null {
  if (post.seller_id === buyerId) return "본인 게시글에는 가격을 제안할 수 없습니다.";
  if (!post.allow_offers) return "이 게시글은 가격 제안을 받지 않습니다.";
  if (post.sold_at !== null) return "이미 판매 완료된 게시글입니다.";
  return null;
}

export function parseOfferAmount(raw: unknown): Result<number> {
  return wholeNumber(raw, "제안 가격", 1, MAX_PRICE);
}

