import { User } from "@supabase/supabase-js";
import { isSchoolEmail } from "../rules/email";
import { env } from "./env";
import { HttpError } from "./http";
import { serverSupabase } from "./supabase";

export function assertMember(user: User) {
  if (!user.email_confirmed_at) throw new HttpError(403, "학교 메일 인증을 완료해 주세요.");
  if (!isSchoolEmail(user.email ?? "", env("SCHOOL_EMAIL_DOMAIN")))
    throw new HttpError(403, "학교 이메일 계정만 이용할 수 있습니다.");
}

/** Called by every board API: logged in + confirmed + school domain. */
export async function requireMember() {
  const supabase = await serverSupabase();
  const { data, error } = await supabase.auth.getUser();
  if (error || !data.user) throw new HttpError(401, "로그인이 필요합니다.");
  assertMember(data.user);
  return { supabase, user: data.user };
}

