import { isSchoolEmail } from "@/lib/rules/email";
import { text } from "@/lib/rules/validate";
import { env } from "@/lib/server/env";
import { clientIp, handle, HttpError } from "@/lib/server/http";
import { rateLimit } from "@/lib/server/rateLimit";
import { serverSupabase } from "@/lib/server/supabase";

export const POST = handle(async (req: Request) => {
  if (!rateLimit(`signup:${clientIp(req)}`, 5, 15 * 60_000)) throw new HttpError(429, "잠시 후 다시 시도해 주세요.");
  const body = await req.json().catch(() => { throw new HttpError(400, "잘못된 요청입니다."); });
  const email = text(body.email, "이메일", 3, 254);
  const password = text(body.password, "비밀번호", 8, 72);
  if (!email.ok) throw new HttpError(400, email.error);
  if (!password.ok) throw new HttpError(400, password.error);
  if (!isSchoolEmail(email.value, env("SCHOOL_EMAIL_DOMAIN")))
    throw new HttpError(400, `@${env("SCHOOL_EMAIL_DOMAIN")} 학교 이메일로만 가입할 수 있습니다.`);
  const sb = await serverSupabase();
  const { error } = await sb.auth.signUp({
    email: email.value, password: password.value,
    options: { emailRedirectTo: `${env("SITE_URL")}/auth/callback` },
  });
  if (error) throw new HttpError(400, error.message);
  return Response.json({ message: "인증 메일을 보냈습니다. 메일의 링크를 눌러 가입을 완료해 주세요." });
});

