import { text } from "@/lib/rules/validate";
import { clientIp, handle, HttpError } from "@/lib/server/http";
import { rateLimit } from "@/lib/server/rateLimit";
import { assertMember } from "@/lib/server/session";
import { serverSupabase } from "@/lib/server/supabase";

export const POST = handle(async (req: Request) => {
  if (!rateLimit(`login:${clientIp(req)}`, 10, 15 * 60_000)) throw new HttpError(429, "로그인 시도가 너무 많습니다. 잠시 후 다시 시도해 주세요.");
  const body = await req.json().catch(() => { throw new HttpError(400, "잘못된 요청입니다."); });
  const email = text(body.email, "이메일", 3, 254);
  const password = text(body.password, "비밀번호", 1, 72);
  if (!email.ok || !password.ok) throw new HttpError(400, "이메일과 비밀번호를 입력해 주세요.");
  const sb = await serverSupabase();
  const { data, error } = await sb.auth.signInWithPassword({ email: email.value, password: password.value });
  if (error || !data.user) throw new HttpError(401, "이메일 또는 비밀번호가 올바르지 않거나 메일 인증이 끝나지 않았습니다.");
  try {
    assertMember(data.user);
  } catch (e) {
    await sb.auth.signOut();
    throw e;
  }
  return Response.json({ ok: true });
});

