import { isVisible } from "@/lib/rules/listing";
import { handle, HttpError } from "@/lib/server/http";
import { POST_COLUMNS, PostRow, toViews } from "@/lib/server/posts";
import { requireMember } from "@/lib/server/session";

type Ctx = { params: Promise<{ id: string }> };

export async function loadPost(sb: Awaited<ReturnType<typeof requireMember>>["supabase"], id: string): Promise<PostRow> {
  if (!/^[0-9a-f-]{36}$/i.test(id)) throw new HttpError(404, "게시글을 찾을 수 없습니다.");
  const { data, error } = await sb.from("posts").select(POST_COLUMNS).eq("id", id).maybeSingle();
  if (error) throw error;
  if (!data || !isVisible(data.sold_at)) throw new HttpError(404, "게시글을 찾을 수 없습니다.");
  return data as PostRow;
}

export const GET = handle(async (_req: Request, ctx: Ctx) => {
  const { supabase, user } = await requireMember();
  const post = await loadPost(supabase, (await ctx.params).id);
  const [view] = await toViews(supabase, [post], user.id);
  return Response.json(view);
});

