import { offerBlockReason, parseOfferAmount } from "@/lib/rules/offer";
import { handle, HttpError } from "@/lib/server/http";
import { requireMember } from "@/lib/server/session";
import { loadPost } from "../route";

type Ctx = { params: Promise<{ id: string }> };

export const GET = handle(async (_req: Request, ctx: Ctx) => {
  const { supabase, user } = await requireMember();
  const post = await loadPost(supabase, (await ctx.params).id);
  if (post.seller_id !== user.id) throw new HttpError(403, "판매자만 제안 목록을 볼 수 있습니다.");
  const { data, error } = await supabase.from("offers").select("id, amount, created_at")
    .eq("post_id", post.id).order("created_at", { ascending: false });
  if (error) throw error;
  return Response.json(data);
});

export const POST = handle(async (req: Request, ctx: Ctx) => {
  const { supabase, user } = await requireMember();
  const post = await loadPost(supabase, (await ctx.params).id);
  const blocked = offerBlockReason(post, user.id);
  if (blocked) throw new HttpError(400, blocked);
  const body = await req.json().catch(() => { throw new HttpError(400, "잘못된 요청입니다."); });
  const amount = parseOfferAmount(body.amount);
  if (!amount.ok) throw new HttpError(400, amount.error);
  const { error } = await supabase.from("offers").insert({ post_id: post.id, buyer_id: user.id, amount: amount.value });
  if (error?.code === "23505") throw new HttpError(409, "이미 이 게시글에 가격을 제안했습니다.");
  if (error) throw error;
  return Response.json({ ok: true }, { status: 201 });
});

