export default function NewPost() {
  const router = useRouter();
  const [msg, setMsg] = useState("");
  async function submit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    try {
      const r = await api<{ id: string }>("/api/posts", { method: "POST", body: new FormData(e.currentTarget) });
      router.push(`/posts/${r.id}`);
    } catch (err) { setMsg((err as Error).message); }
  }
  return (
    <form onSubmit={submit}>
      <h1>판매글 쓰기</h1>
      <input name="title" placeholder="교재 제목" maxLength={100} required />
      <textarea name="description" placeholder="상태, 필기 여부 등" maxLength={2000} />
      <input name="price" type="number" min={0} step={1} placeholder="판매 가격(원)" required />
      <label><input type="radio" name="allowOffers" value="true" required /> 가격 제안 받기</label>
      <label><input type="radio" name="allowOffers" value="false" /> 가격 제안 안 받기</label>
      <input name="photo" type="file" accept="image/jpeg,image/png,image/webp" required />
      <button>등록</button>
      {msg && <p role="alert">{msg}</p>}
    </form>
  );
}

